const assert=require('node:assert/strict');const path=require('node:path');const root=process.argv[2];const m=require(path.join(root,'tools/rpg-2-star-ocean-the-second_production-completion_ledger-cli_v01_20261018-140533-3b436630.js'));const original=m.load(path.join(root,m.LEDGER_REL));assert.deepEqual(m.validate(original,root),[]);let checks=0;for(const id of ['content.char.lin-que.idle-anim','qa.char.lin-que.runtime-set-check','review.char.lin-que.runtime-set','ops.inspection']){const t=original.tasks.find(x=>x.id===id)||original.tasks.find(x=>x.stage==='operations');const l=structuredClone(original);const before=m.compute(l,root);m.reassign(l,root,{task:t.id,owner:'hermes',reasonEn:'Creator-authorized Hermes takeover',now:new Date().toISOString()});assert.deepEqual(m.validate(l,root),[]);const after=m.compute(l,root);for(const k of ['production','inspection','approval','release','stageTotals'])assert.deepEqual(after[k],before[k]);assert.equal(l.tasks.length,original.tasks.length);assert.equal(l.tasks.find(x=>x.id===t.id).owner,'hermes');m.reassign(l,root,{task:t.id,owner:t.owner,reasonEn:'Invariant-test reverse transfer',now:new Date().toISOString()});assert.deepEqual(m.validate(l,root),[]);checks++;}for(const t of original.tasks.filter(x=>x.owner==='creator').filter((x,i,a)=>a.findIndex(t=>t.type===x.type)===i)){const l=structuredClone(original);assert.throws(()=>m.reassign(l,root,{task:t.id,owner:'hermes',reasonEn:'must refuse',now:new Date().toISOString()}));assert.deepEqual(l,original);checks++;}console.log('HERMES_OWNER_INVARIANTS_PASS',checks);